    // Thread/block indices
    mov.u32         %r30, %tid.x;
    mov.u32         %r31, %tid.y;
    mov.u32         %r32, %ctaid.x;
    mov.u32         %r33, %ctaid.y;
    mov.u32         %r34, %ctaid.z;
    mov.u32         %r35, %ntid.x;
