    // Base for input: baseN = n * (Cin*HW)
    cvt.u64.u32     %rd31, %r42;          // n
    mul.lo.u64      %rd32, %rd31, %rd24;  // baseN
    // Base for output linear index
    // out_index = (((n*Cout + oc)*OH + oh)*OW + ow)
